class KVStoreError(Exception):
    pass


class RecordError(KVStoreError):
    pass


class IncompleteRecordError(RecordError):
    pass


class CorruptRecordError(RecordError):
    pass


class CorruptSegmentError(KVStoreError):
    def __init__(
        self,
        path: pathlib.Path | str,
        offset: int,
        reason: str | None = None,
    ) -> None:
        self.path = pathlib.Path(path)
        self.offset = int(offset)
        self.reason = reason

    def __str__(self) -> str:
        if self.reason is None:
            return f"{self.path.name} at offset {self.offset}"
        return f"{self.path.name} at offset {self.offset}: {self.reason}"

import struct
import zlib

from .errors import CorruptRecordError, IncompleteRecordError

MAGIC = b"KVR1"


def encode_record(key: str, value: str | None) -> bytes:
    if not isinstance(key, str):
        raise TypeError("key must be str")
    if value is not None and not isinstance(value, str):
        raise TypeError("value must be str or None")

    key_bytes = key.encode("utf-8")
    if not 1 <= len(key_bytes) <= 65535:
        raise ValueError("key byte length out of range")

    if value is None:
        flags = 0x01
        value_bytes = b""
    else:
        flags = 0x00
        value_bytes = value.encode("utf-8")

    header = (
        MAGIC
        + bytes([flags])
        + struct.pack(">H", len(key_bytes))
        + struct.pack(">I", len(value_bytes))
        + struct.pack(">I", zlib.crc32(key_bytes + value_bytes) & 0xFFFFFFFF)
    )
    return header + key_bytes + value_bytes


def decode_record(buf: bytes, offset: int = 0) -> tuple[str, str | None, int]:
    start = offset
    if len(buf) - start < 15:
        raise IncompleteRecordError("header is incomplete")

    header = buf[start : start + 15]
    if header[0:4] != MAGIC:
        raise CorruptRecordError("bad magic")

    flags = header[4]
    if flags not in (0x00, 0x01):
        raise CorruptRecordError("unknown flags")

    key_len = struct.unpack(">H", header[5:7])[0]
    if key_len == 0:
        raise CorruptRecordError("key_len is zero")

    value_len = struct.unpack(">I", header[7:11])[0]
    if flags == 0x01 and value_len != 0:
        raise CorruptRecordError("tombstone has non-zero value_len")

    total_size = 15 + key_len + value_len
    if len(buf) - start < total_size:
        raise IncompleteRecordError("record extends beyond buffer")

    crc = struct.unpack(">I", header[11:15])[0]
    key_start = start + 15
    key_bytes = buf[key_start : key_start + key_len]
    value_start = key_start + key_len
    value_bytes = buf[value_start : value_start + value_len]

    if (zlib.crc32(key_bytes + value_bytes) & 0xFFFFFFFF) != crc:
        raise CorruptRecordError("CRC mismatch")

    try:
        key = key_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptRecordError("key is not valid UTF-8") from exc

    if flags == 0x01:
        return (key, None, total_size)

    try:
        value = value_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptRecordError("value is not valid UTF-8") from exc
    return (key, value, total_size)

import os
import pathlib
from collections.abc import Iterator

from .errors import CorruptRecordError, CorruptSegmentError
from .record import decode_record, IncompleteRecordError


class Segment:
    def __init__(self, path: pathlib.Path, seg_id: int) -> None:
        self._path = pathlib.Path(path)
        self._seg_id = int(seg_id)
        self._file = open(self._path, "ab+")

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def size(self) -> int:
        self._file.seek(0, os.SEEK_END)
        return int(self._file.tell())

    def append(self, blob: bytes) -> int:
        offset = self.size
        self._file.seek(0, os.SEEK_END)
        self._file.write(blob)
        self._file.flush()
        os.fsync(self._file.fileno())
        return offset

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        self._file.seek(0)
        data = self._file.read()
        pos = 0
        while pos < len(data):
            remaining = len(data) - pos
            if remaining < 15:
                break
            try:
                key, value, total_size = decode_record(data, pos)
            except IncompleteRecordError:
                break
            except CorruptRecordError as exc:
                raise CorruptSegmentError(self._path, pos, str(exc)) from exc
            yield (key, value, pos)
            pos += total_size

    def close(self) -> None:
        if not self._file.closed:
            self._file.close()

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Location:
    seg_id: int
    offset: int


class Index:
    def __init__(self) -> None:
        self._entries: dict[str, tuple[Location, bool]] = {}

    def put(self, key: str, loc: Location, *, tombstone: bool) -> None:
        self._entries[key] = (loc, tombstone)

    def get(self, key: str) -> Location | None:
        item = self._entries.get(key)
        if item is None or item[1]:
            return None
        return item[0]

    def live_keys(self) -> list[str]:
        live = []
        for key, (loc, tombstone) in self._entries.items():
            if not tombstone:
                live.append((loc, key))
        live.sort(key=lambda item: (item[0].seg_id, item[0].offset))
        return [key for _, key in live]

    def tombstone_count(self) -> int:
        return sum(1 for _, tombstone in self._entries.values() if tombstone)

    def __len__(self) -> int:
        return sum(1 for _, tombstone in self._entries.values() if not tombstone)

